1	import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
2	import * as crypto from 'crypto';
3	import * as bcrypt from 'bcryptjs';
4	import { SupabaseService } from '../supabase/supabase.service';
5	
6	export interface CriarGarcomBody {
7	  nome: string;
8	  telefone?: string;
9	  senha: string;
10	  permissoes?: { pagamento_parcial?: boolean };
11	}
12	
13	export interface AtualizarGarcomBody {
14	  nome?: string;
15	  telefone?: string;
16	  ativo?: boolean;
17	  senha?: string;
18	  permissoes?: { pagamento_parcial?: boolean };
19	}
20	
21	export interface ComissaoConfigBody {
22	  nome: string;
23	  tipo: 'percentual' | 'fixo';
24	  valor: number;
25	  base_calculo?: 'total_vendido' | 'total_recebido';
26	  ativo?: boolean;
27	}
28	
29	@Injectable()
30	export class GarconsService {
31	  constructor(private supabase: SupabaseService) {}
32	
33	  private gerarLoginKey(): string {
34	    return crypto.randomBytes(4).toString('hex');
35	  }
36	
37	  async criar(restaurantId: number, body: CriarGarcomBody) {
38	    if (!body.nome) throw new BadRequestException('Nome é obrigatório');
39	    if (!body.senha || body.senha.length < 4) throw new BadRequestException('Senha deve ter no mínimo 4 caracteres');
40	
41	    const passwordHash = await bcrypt.hash(body.senha, 10);
42	    let loginKey = this.gerarLoginKey();
43	
44	    for (let tentativas = 0; tentativas < 5; tentativas++) {
45	      const { data: existente } = await this.supabase.client
46	        .from('garcons')
47	        .select('id')
48	        .eq('login_key', loginKey)
49	        .maybeSingle();
50	      if (!existente) break;
51	      loginKey = this.gerarLoginKey();
52	    }
53	
54	    const { data, error } = await this.supabase.client
55	      .from('garcons')
56	      .insert({
57	        restaurant_id: restaurantId,
58	        nome: body.nome,
59	        telefone: body.telefone ?? null,
60	        login_key: loginKey,
61	        password_hash: passwordHash,
62	        permissoes: {
63	          // Default true — pagamento parcial já era permitido sem restrição antes dessa
64	          // permissão existir, então continua liberado por padrão.
65	          pagamento_parcial: body.permissoes?.pagamento_parcial !== false,
66	        },
67	      })
68	      .select('id, nome, telefone, login_key, ativo, permissoes, created_at')
69	      .single();
70	    if (error) throw error;
71	
72	    return data;
73	  }
74	
75	  async listar(restaurantId: number) {
76	    const { data, error } = await this.supabase.client
77	      .from('garcons')
78	      .select('id, nome, telefone, login_key, ativo, permissoes, ultimo_acesso_em, active_session_id, session_expires_at, created_at')
79	      .eq('restaurant_id', restaurantId)
80	      .order('created_at', { ascending: false });
81	    if (error) throw error;
82	
83	    const agora = Date.now();
84	    return (data ?? []).map(({ active_session_id, session_expires_at, ...resto }) => ({
85	      ...resto,
86	      sessao_ativa: !!active_session_id && !!session_expires_at && new Date(session_expires_at).getTime() > agora,
87	    }));
88	  }
89	
90	  private async garantirPertence(id: number, restaurantId: number) {
91	    const { data } = await this.supabase.client
92	      .from('garcons')
93	      .select('id')
94	      .eq('id', id)
95	      .eq('restaurant_id', restaurantId)
96	      .maybeSingle();
97	    if (!data) throw new NotFoundException('Garçom não encontrado');
98	  }
99	
100	  async atualizar(id: number, restaurantId: number, body: AtualizarGarcomBody) {
101	    await this.garantirPertence(id, restaurantId);
102	
103	    const update: Record<string, unknown> = {};
104	    if (body.nome !== undefined) update.nome = body.nome;
105	    if (body.telefone !== undefined) update.telefone = body.telefone;
106	    if (body.ativo !== undefined) update.ativo = body.ativo;
107	    if (body.permissoes !== undefined) {
108	      update.permissoes = {
109	        pagamento_parcial: body.permissoes.pagamento_parcial !== false,
110	      };
111	    }
112	    if (body.senha) {
113	      if (body.senha.length < 4) throw new BadRequestException('Senha deve ter no mínimo 4 caracteres');
114	      update.password_hash = await bcrypt.hash(body.senha, 10);
115	    }
116	
117	    const { data, error } = await this.supabase.client
118	      .from('garcons')
119	      .update(update)
120	      .eq('id', id)
121	      .select('id, nome, telefone, login_key, ativo, permissoes, created_at')
122	      .single();
123	    if (error) throw error;
124	
125	    return data;
126	  }
127	
128	  async remover(id: number, restaurantId: number) {
129	    await this.garantirPertence(id, restaurantId);
130	    const { error } = await this.supabase.client.from('garcons').delete().eq('id', id);
131	    if (error) throw error;
132	    return { ok: true };
133	  }
134	
135	  // Libera o garçom pra logar em outro dispositivo, encerrando a sessão travada.
136	  async forcarLogout(id: number, restaurantId: number) {
137	    await this.garantirPertence(id, restaurantId);
138	    const { error } = await this.supabase.client
139	      .from('garcons')
140	      .update({ active_session_id: null, session_expires_at: null })
141	      .eq('id', id);
142	    if (error) throw error;
143	    return { ok: true };
144	  }
145	
146	  async garconsOnline(restaurantId: number) {
147	    const limite = new Date(Date.now() - 5 * 60 * 1000).toISOString();
148	    const { data, error } = await this.supabase.client
149	      .from('garcons')
150	      .select('id, nome, ultimo_acesso_em')
151	      .eq('restaurant_id', restaurantId)
152	      .eq('ativo', true)
153	      .gte('ultimo_acesso_em', limite);
154	    if (error) throw error;
155	    return data;
156	  }
157	
158	  // Regras de comissão são do estabelecimento (não por garçom) — todo garçom que fecha
159	  // uma comanda gera lançamento pra cada regra ativa (ver lancarComissoes no salao-pdv.service).
160	  async listarComissoesConfig(restaurantId: number) {
161	    const { data, error } = await this.supabase.client
162	      .from('garcom_comissoes_config')
163	      .select('id, nome, tipo, valor, base_calculo, ativo, created_at')
164	      .eq('restaurant_id', restaurantId)
165	      .order('created_at', { ascending: false });
166	    if (error) throw error;
167	    return data;
168	  }
169	
170	  async criarComissaoConfig(restaurantId: number, body: ComissaoConfigBody) {
171	    if (!body.nome) throw new BadRequestException('Nome é obrigatório');
172	    if (!body.tipo || !['percentual', 'fixo'].includes(body.tipo)) throw new BadRequestException('Tipo inválido');
173	    if (body.valor === undefined || body.valor === null || body.valor < 0) throw new BadRequestException('Valor inválido');
174	
175	    const { data, error } = await this.supabase.client
176	      .from('garcom_comissoes_config')
177	      .insert({
178	        restaurant_id: restaurantId,
179	        nome: body.nome,
180	        tipo: body.tipo,
181	        valor: body.valor,
182	        base_calculo: body.base_calculo ?? 'total_vendido',
183	        ativo: body.ativo !== false,
184	      })
185	      .select('id, nome, tipo, valor, base_calculo, ativo, created_at')
186	      .single();
187	    if (error) throw error;
188	    return data;
189	  }
190	
191	  private async garantirComissaoConfigPertence(id: number, restaurantId: number) {
192	    const { data } = await this.supabase.client
193	      .from('garcom_comissoes_config')
194	      .select('id')
195	      .eq('id', id)
196	      .eq('restaurant_id', restaurantId)
197	      .maybeSingle();
198	    if (!data) throw new NotFoundException('Regra de comissão não encontrada');
199	  }
200	
201	  async atualizarComissaoConfig(id: number, restaurantId: number, body: Partial<ComissaoConfigBody>) {
202	    await this.garantirComissaoConfigPertence(id, restaurantId);
203	
204	    const update: Record<string, unknown> = {};
205	    if (body.nome !== undefined) update.nome = body.nome;
206	    if (body.tipo !== undefined) {
207	      if (!['percentual', 'fixo'].includes(body.tipo)) throw new BadRequestException('Tipo inválido');
208	      update.tipo = body.tipo;
209	    }
210	    if (body.valor !== undefined) {
211	      if (body.valor < 0) throw new BadRequestException('Valor inválido');
212	      update.valor = body.valor;
213	    }
214	    if (body.base_calculo !== undefined) update.base_calculo = body.base_calculo;
215	    if (body.ativo !== undefined) update.ativo = body.ativo;
216	
217	    const { data, error } = await this.supabase.client
218	      .from('garcom_comissoes_config')
219	      .update(update)
220	      .eq('id', id)
221	      .select('id, nome, tipo, valor, base_calculo, ativo, created_at')
222	      .single();
223	    if (error) throw error;
224	    return data;
225	  }
226	
227	  async removerComissaoConfig(id: number, restaurantId: number) {
228	    await this.garantirComissaoConfigPertence(id, restaurantId);
229	    const { error } = await this.supabase.client.from('garcom_comissoes_config').delete().eq('id', id);
230	    if (error) throw error;
231	    return { ok: true };
232	  }
233	}
